// ─── File: SshDiagDemo.java ───
package com.bank.sshdiag;

import java.util.logging.*;

public class SshDiagDemo {
    private static final Logger log = Logger.getLogger("SshDiag");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // A broken case: SG does not allow port 22 from the engineer's IP.
        ConnectivityState broken = new ConnectivityState();
        broken.running = true;
        broken.statusChecksPassed = true;
        broken.sgAllowsPort22 = false;     // <-- the fault
        broken.naclAllowsBothDirections = true;
        broken.routeToIgwPresent = true;
        broken.hasPublicIp = true;
        broken.correctKeyAndUser = true;
        broken.osFirewallAllows22 = true;

        SshDiagnostic diag = new SshDiagnostic();
        String result = diag.diagnose(broken);
        log.warning(() -> "Diagnosis: " + result);

        // A healthy case.
        ConnectivityState ok = new ConnectivityState();
        ok.running = ok.statusChecksPassed = ok.sgAllowsPort22 = true;
        ok.naclAllowsBothDirections = ok.routeToIgwPresent = ok.hasPublicIp = true;
        ok.correctKeyAndUser = ok.osFirewallAllows22 = true;
        log.info(() -> "Diagnosis: " + diag.diagnose(ok));
    }
}

// ─── Would be in ConnectivityState.java ───
class ConnectivityState {
    boolean running, statusChecksPassed, sgAllowsPort22, naclAllowsBothDirections;
    boolean routeToIgwPresent, hasPublicIp, correctKeyAndUser, osFirewallAllows22;
}

// ─── Would be in SshDiagnostic.java ───
class SshDiagnostic {
    // Walk layers outermost-cause-first and report the first failing layer.
    String diagnose(ConnectivityState s) {
        if (!s.running) return "Instance not running — start it";
        if (!s.statusChecksPassed) return "Status checks failing — check system log, sshd may be down";
        if (!s.sgAllowsPort22) return "Security Group: add inbound TCP 22 from your IP";
        if (!s.naclAllowsBothDirections) return "NACL: allow inbound 22 AND outbound ephemeral 1024-65535";
        if (!s.routeToIgwPresent) return "Route table: add 0.0.0.0/0 to internet gateway";
        if (!s.hasPublicIp) return "No public IP — use bastion host or SSM Session Manager";
        if (!s.correctKeyAndUser) return "Key/user: wrong .pem or username (ec2-user/ubuntu)";
        if (!s.osFirewallAllows22) return "OS firewall (iptables/firewalld) blocking 22 — open it";
        return "All layers OK — SSH should succeed";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
